function configurationMessage(readiness: ExpenseSnapshot['readiness'], th: boolean) {
  const pairs: Record<string,[string,string]> = {
    schema_unavailable:['Expense saving is unavailable on this database: the reviewed Expenses schema is not installed. Add Expense stays locked until an approved non-production activation.','ยังบันทึกค่าใช้จ่ายบนฐานข้อมูลนี้ไม่ได้ เพราะยังไม่ได้ติดตั้งสคีมาที่ตรวจแล้ว ปุ่มเพิ่มค่าใช้จ่ายจะถูกล็อกจนกว่าจะเปิดใช้บนสภาพแวดล้อมที่อนุมัติ'],
    schema_upgrade_required:['Expense saving is unavailable until the Expenses schema is upgraded to version 3 on an approved environment.','ยังบันทึกไม่ได้จนกว่าจะอัปเกรดสคีมาค่าใช้จ่ายเป็นเวอร์ชัน 3 บนสภาพแวดล้อมที่อนุมัติ'],
    private_storage_required:['Expense saving is unavailable until the private expenses-receipts storage bucket is configured.','ยังบันทึกไม่ได้จนกว่าจะตั้งค่าบัคเก็ตใบเสร็จส่วนตัว expenses-receipts'],
    activation_required:['Expense saving is unavailable until the approved environment gates and expenses_config.enabled are activated.','ยังบันทึกไม่ได้จนกว่าจะเปิดเกตสภาพแวดล้อมที่อนุมัติและ expenses_config.enabled']
  };
  const pair = pairs[readiness || 'schema_unavailable'] || pairs.activation_required;
  return pair[th?1:0];
}
function errorMessage(error: unknown, th: boolean) {
  const code = error instanceof Error ? error.message : '';
  const pairs: [RegExp,string,string][] = [
    [/BOOKING_LINK|BOOKING_UNAVAILABLE/,'The expense draft is retained, but the booking link was not confirmed. Reopen the draft, check the job, or remove the optional link and retry.','ร่างค่าใช้จ่ายยังอยู่ แต่ยังยืนยันลิงก์งานไม่ได้ เปิดร่างใหม่ ตรวจงาน หรือนำลิงก์ที่ไม่บังคับออกแล้วลองใหม่'],
    [/REGISTER_CHANGED|EXPORT_LIMIT/,'The register changed during export or exceeds 10,000 rows. Refresh or narrow the filters and try again.','ทะเบียนเปลี่ยนระหว่างส่งออก หรือเกิน 10,000 รายการ รีเฟรชหรือจำกัดตัวกรองแล้วลองใหม่'],
    [/INVALID_FILTER|INVALID_SORT|INVALID_PAGE/,'Check the date range and register filters.','ตรวจช่วงวันที่และตัวกรองทะเบียน'],
    [/SAFE_ENVIRONMENT|NOT_ACTIVATED|SCHEMA|LOOKUP_UNAVAILABLE|PRIVATE_STORAGE/,'Expense saving is not activated for this environment.','ยังไม่เปิดการบันทึกในสภาพแวดล้อมนี้'],
    [/TEMPLATE_CONFIRMATION/,'Confirm the actual invoice and amount before submitting this recurring expense.','ยืนยันใบแจ้งหนี้และยอดจริงก่อนส่งค่าใช้จ่ายประจำนี้'],
    [/PAYMENT_AMOUNT|PAYMENT_STATUS/,'Enter the cumulative payment: zero for unpaid, less than the total for partial, or the full total for paid.','กรอกยอดชำระสะสม: ศูนย์สำหรับยังไม่ชำระ น้อยกว่ายอดรวมสำหรับบางส่วน หรือเต็มยอดเมื่อชำระแล้ว'],
    [/AMOUNT/,'Enter a positive THB total with at most two decimal places. VAT cannot exceed the total.','ระบุยอดบาทที่มากกว่าศูนย์ ทศนิยมไม่เกินสองตำแหน่ง VAT ต้องไม่เกินยอดรวม'],
    [/DATE/,'Choose a valid expense date.','เลือกวันที่ค่าใช้จ่ายที่ถูกต้อง'],
    [/MISSING_RECEIPT/,'Attach a receipt or explain why it is missing.','แนบใบเสร็จหรือระบุเหตุผลที่ไม่มี'],
    [/FILE_SIZE|TOO_LARGE/,'Each file must be between 1 byte and 15 MB.','แต่ละไฟล์ต้องมีขนาด 1 ไบต์ถึง 15 MB'],
    [/FILE_TYPE/,'Use an original JPG, PNG, WebP, HEIC, HEIF or PDF file.','ใช้ไฟล์ต้นฉบับ JPG, PNG, WebP, HEIC, HEIF หรือ PDF'],
    [/ATTACHMENT_LIMIT/,'An expense can have up to 12 attachments.','แนบได้สูงสุด 12 ไฟล์ต่อรายการ'],
    [/UPLOAD|ATTACHMENT_LOOKUP/,'The draft is saved, but an upload is incomplete. Choose the same file and retry, or remove the pending file with a reason.','บันทึกร่างแล้ว แต่อัปโหลดไม่ครบ เลือกไฟล์เดิมเพื่อลองใหม่ หรือนำไฟล์ที่ค้างออกพร้อมเหตุผล'],
    [/REQUEST_UNCONFIRMED/,'The result could not be confirmed. Refresh the register and check the draft before retrying.','ยังยืนยันผลไม่ได้ รีเฟรชทะเบียนและตรวจร่างก่อนลองอีกครั้ง'],
    [/CONFLICT/,'This record changed in another session. Refresh and reopen it before editing.','รายการถูกเปลี่ยนจากอีกเซสชัน รีเฟรชแล้วเปิดใหม่ก่อนแก้ไข'],
    [/SELF_APPROVAL/,'Another manager must approve this expense.','ผู้จัดการท่านอื่นต้องเป็นผู้อนุมัติรายการนี้'],
    [/REVIEW_NOTE|VOID_NOTE|REMOVAL_REASON|PAYMENT/,'Add a reason or payment evidence before continuing. Close only after payment is confirmed.','เพิ่มเหตุผลหรือหลักฐานการชำระก่อนดำเนินการ ปิดรายการได้หลังยืนยันชำระแล้ว'],
    [/FORBIDDEN|READ_ONLY|REQUIRED|NOT_ALLOWED|LOCKED/,'Check required fields and your permission for this action.','ตรวจช่องที่จำเป็นและสิทธิ์ในการดำเนินการ'],
    [/SOURCE/,'Choose a recognised source and enter its existing record reference.','เลือกแหล่งข้อมูลและระบุอ้างอิงรายการเดิม'],
    [/INACTIVE|NOT_FOUND/,'The selected category, vehicle or cost centre is unavailable. Refresh and choose an active option.','หมวดหมู่ รถ หรือศูนย์ต้นทุนไม่พร้อมใช้งาน รีเฟรชและเลือกตัวเลือกที่ใช้งานอยู่'],
    [/SESSION/,'Your session has ended. Sign in again; your text draft remains in this tab where supported.','เซสชันสิ้นสุด กรุณาเข้าสู่ระบบอีกครั้ง ร่างข้อความยังอยู่ในแท็บเมื่อรองรับ']
  ];
  const pair=pairs.find(([re])=>re.test(code)); return pair ? pair[th?2:1] : th?'ดำเนินการไม่สำเร็จ ลองรีเฟรชและทำอีกครั้ง':'The action could not be completed. Refresh and try again.';
}

