    if(fixture){const existing=bookingLinksRef.current[id];if((existing?.revision||0)!==revision)throw new Error('BOOKING_LINK_CONFLICT');const booking=booking_id?FIXTURE_BOOKINGS.find(b=>b.id===booking_id):null;if(booking_id&&!booking)throw new Error('BOOKING_UNAVAILABLE');link={expense_id:id,booking_id,revision:revision+1,note:'Synthetic booking selection',booking};const old=stateRef.current;const next={...old,audit:[{id:crypto.randomUUID(),expense_id:id,actor:old.user_id,action:'booking_link',note:link.note,old_value:existing||null,new_value:link,created_at:new Date().toISOString()},...old.audit]};stateRef.current=next;setSnapshot(next);}
