  async function printReport(){if(exportLock.current)return;exportLock.current=true;setExporting(true);const requested=queryKey;try{setPrintRows(await allFilteredRows(true));setTimeout(()=>{if(queryKeyRef.current===requested)window.print();else{setPrintRows(null);reportError(new Error('REGISTER_CHANGED_RETRY'));}},100);}catch(e){reportError(e);}finally{exportLock.current=false;setExporting(false);}}
  async function download(excel:boolean){if(exportLock.current)return;exportLock.current=true;setExporting(true);try{const data=exportRows(await allFilteredRows(),th);const basis=t('Standalone submitted / needs information / approved / closed; excludes linked sources, customer charges, drafts, rejections and voids.','นับเฉพาะค่าใช้จ่ายใหม่ที่ส่งตรวจ ต้องการข้อมูล อนุมัติ หรือปิดแล้ว ไม่รวมต้นทางที่เชื่อม ยอดลูกค้า ร่าง ไม่อนุมัติ และยกเลิก');const reporting={Mode:fixture?'SYNTHETIC FIXTURE ONLY - NOT COMPANY RECORDS':'Authenticated saved records',DateBasis:'Expense date; cumulative payments on those expenses, not payment-date cash flow',CashColumns:t('PaidTHB / OutstandingTHB are per-record balances. SpendingPaidTHB / SpendingOutstandingTHB apply the standalone spending basis.','PaidTHB / OutstandingTHB เป็นยอดต่อรายการ ส่วน SpendingPaidTHB / SpendingOutstandingTHB ใช้หลักเกณฑ์ค่าใช้จ่ายใหม่'),Basis:basis,From:filters.from,To:filters.to,Filters:JSON.stringify({...filters,status:visibleTab==='pending'?'submitted':filters.status,sort}),Visibility:t('Only records authorised for the current user','เฉพาะรายการที่ผู้ใช้มีสิทธิ์'),Generated:new Date().toISOString()};const xlsx=await import('xlsx');const book=xlsx.utils.book_new();xlsx.utils.book_append_sheet(book,xlsx.utils.json_to_sheet(data),'Expenses');xlsx.utils.book_append_sheet(book,xlsx.utils.json_to_sheet([reporting]),'Reporting basis');if(excel)xlsx.writeFile(book,`EES-expenses-${filters.from}-${filters.to}.xlsx`);else{const sheet=xlsx.utils.aoa_to_sheet([[basis],[JSON.stringify(reporting)],[],...xlsx.utils.sheet_to_json<unknown[]>(book.Sheets.Expenses,{header:1})]);const blob=new Blob(['\ufeff',xlsx.utils.sheet_to_csv(sheet)],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`EES-expenses-${filters.from}-${filters.to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}catch(e){reportError(e);}finally{exportLock.current=false;setExporting(false);}}
