  function ledger(items:Expense[],compact=false){return items.length?<div className={s.tableWrap}><table className={s.table}><thead><tr>{(compact?[t('Expense','ค่าใช้จ่าย'),t('Allocation','จัดสรร'),t('Amount','ยอดเงิน'),t('Approval','การอนุมัติ')]:[t('Date / ID','วันที่ / รหัส'),t('Description','รายละเอียด'),t('Category','หมวดหมู่'),t('Registration / Centre','ทะเบียน / ศูนย์'),t('Supplier','ผู้ขาย'),t('Amount · THB','ยอดเงิน · บาท'),t('Receipt','ใบเสร็จ'),t('Submitted by','ผู้ส่ง'),t('Approval','การอนุมัติ'),t('Payment','การชำระเงิน')]).map(h=><th key={h} scope="col">{h}</th>)}</tr></thead><tbody>{items.map(e=><tr key={e.id}>{compact?<><td><button className={s.link} onClick={()=>open(e.id)}>{e.data.description}</button><p className={s.muted}>{e.data.date}</p></td><td><strong>{allocation(e)}</strong></td><td>฿{money(e.data.amount_satang)}</td><td><Status status={e.status} th={th}/></td></>:<><td>{e.data.date}<p className={s.muted}>{e.id.slice(0,8)}</p></td><td><button className={s.link} onClick={()=>open(e.id)}>{e.data.description}</button>{e.data.source!=='standalone'?<p className={s.muted}>{t('Linked · excluded from totals','เชื่อมต้นทาง · ไม่นับรวม')}</p>:null}</td><td>{th?e.data.category_th:e.data.category_en}</td><td><strong>{allocation(e)}</strong></td><td>{e.data.supplier||'—'}</td><td className="font-semibold">฿{money(e.data.amount_satang)}</td><td>{snapshot.attachments.some(a=>a.expense_id===e.id&&a.state==='ready')?<span className={s.badge} data-status="approved">{snapshot.attachments.filter(a=>a.expense_id===e.id&&a.state==='ready').length} {t('files','ไฟล์')}</span>:<span className={s.badge} data-status="needs_information">{t('Missing','ไม่มี')}</span>}</td><td>{e.data.submitted_by}</td><td><Status status={e.status} th={th}/></td><td><span className={s.badge} data-status={e.data.payment_status}>{e.data.payment_status==='paid'?t('Paid','ชำระแล้ว'):t('Unpaid','ยังไม่ชำระ')}</span></td></>}</tr>)}</tbody></table></div>:empty;}
